with lines as (select id, customer_id, key, attr_value from carts lateral view outer explode(attributes) e as key, attr_value) select key, size(collect_set(key)) as num_keys, sort_array(collect_set(key)) as key_list, count_if(key = 'utm_source') as utm_source_events, sort_array(collect_set(key)) as key_list_2, count(*) filter (where key = 'weight_kg') as weight_kg_rows, count(*) as row_count from lines group by 1;
